import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');
const loadRobotoMono = makeLoadFont('RobotoMono');

const { fontFamily: spaceGrotesk } = loadSpaceGrotesk();
const { fontFamily: robotoMono } = loadRobotoMono();



export type ImageFormatErrorProps = Record<string, any>;

const SvgGrid: React.FC<{ color: string }> = ({ color }) => (
  <svg
    width="100%"
    height="100%"
    style={{ position: "absolute", zIndex: 0, opacity: 0.15 }}
  >
    <defs>
      <pattern
        id="bgGrid"
        width="80"
        height="80"
        patternUnits="userSpaceOnUse"
      >
        <path
          d="M 80 0 L 0 0 0 80"
          fill="none"
          stroke={color}
          strokeWidth="2"
        />
      </pattern>
    </defs>
    <rect width="100%" height="100%" fill="url(#bgGrid)" />
  </svg>
);

const Scanlines: React.FC = () => (
  <svg
    width="100%"
    height="100%"
    style={{ position: "absolute", zIndex: 50, pointerEvents: "none", opacity: 0.2 }}
  >
    <defs>
      <pattern id="scan" width="4" height="6" patternUnits="userSpaceOnUse">
        <rect width="4" height="3" fill="transparent" />
        <rect y="3" width="4" height="3" fill="#000000" />
      </pattern>
    </defs>
    <rect width="100%" height="100%" fill="url(#scan)" />
  </svg>
);

const BrokenImageIcon: React.FC<{ color: string; size: number; isGlitch: boolean }> = ({
  color,
  size,
  isGlitch,
}) => {
  const xOffset = isGlitch ? -5 : 0;
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke={color}
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      style={{
        transform: `translateX(${xOffset}px)`,
        filter: isGlitch ? "drop-shadow(3px 0px 0px cyan) drop-shadow(-3px 0px 0px red)" : "none",
        transition: "none",
      }}
    >
      <rect x="3" y="3" width="18" height="18" rx="2" ry="2" />
      <circle cx="8.5" cy="8.5" r="1.5" />
      <polyline points="21 15 16 10 5 21" />
      <line x1="3" y1="3" x2="21" y2="21" />
    </svg>
  );
};

const GlitchText: React.FC<{
  text: string;
  frame: number;
  baseColor: string;
  fontFamily: string;
  fontSize: number;
  fontWeight: number | string;
}> = ({ text, frame, baseColor, fontFamily, fontSize, fontWeight }) => {
  const glitchSeed = random(`text-glitch-${text}-${frame}`);
  const isGlitch = glitchSeed > 0.92;
  const offX1 = isGlitch ? random(`g1-${frame}`) * 16 - 8 : 0;
  const offX2 = isGlitch ? random(`g2-${frame}`) * 16 - 8 : 0;
  const offY1 = isGlitch ? random(`g3-${frame}`) * 8 - 4 : 0;

  return (
    <div
      style={{
        position: "relative",
        display: "inline-block",
        fontFamily,
        fontSize,
        fontWeight,
        transition: "none",
      }}
    >
      {isGlitch && (
        <>
          <div
            style={{
              position: "absolute",
              top: offY1,
              left: offX1,
              color: "#00FFFF",
              mixBlendMode: "screen",
              opacity: 0.8,
              whiteSpace: "pre-wrap",
            }}
          >
            {text}
          </div>
          <div
            style={{
              position: "absolute",
              top: -offY1,
              left: offX2,
              color: "#FF0044",
              mixBlendMode: "screen",
              opacity: 0.8,
              whiteSpace: "pre-wrap",
            }}
          >
            {text}
          </div>
        </>
      )}
      <div
        style={{
          position: "relative",
          zIndex: 1,
          color: isGlitch ? "#FFFFFF" : baseColor,
          whiteSpace: "pre-wrap",
        }}
      >
        {text}
      </div>
    </div>
  );
};

const ImageFormatError: React.FC<ImageFormatErrorProps> = ({
  backgroundColor = "#09090b",
  transparentBackground = false,
  durationInSeconds = 10,
  title = "ERROR DE FORMATO",
  subtitle = "Imágenes incompatibles detectadas en la secuencia.",
  accentColor = "#FF2A55",
  errorCodes = [
    "ERR_JPG_CORRUPT_HEADER",
    "UNSUPPORTED_CODEC_WEBP",
    "PNG_UNEXPECTED_EOF",
    "RENDER_FATAL_FAILURE",
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const totalFrames = Math.floor(durationInSeconds * fps);

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Global 3D Scene Rotation
  const globalRotateX = interpolate(frame, [0, totalFrames], [15, -5]);
  const globalRotateY = interpolate(frame, [0, totalFrames], [-10, 10]);
  const sceneZ = interpolate(
    spring({ fps, frame: frame - 5, config: { damping: 15 } }),
    [0, 1],
    [-800, 0]
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden", transition: "none" }}>
      <SvgGrid color={accentColor} />
      <Scanlines />

      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          perspective: "1200px",
          transformStyle: "preserve-3d",
          transition: "none",
        }}
      >
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            width: "100%",
            transform: `translateZ(${sceneZ}px) rotateX(${globalRotateX}deg) rotateY(${globalRotateY}deg)`,
            transformStyle: "preserve-3d",
            transition: "none",
          }}
        >
          {/* Header Section */}
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              marginBottom: height * 0.08,
              transform: "translateZ(100px)",
              textAlign: "center",
              width: "85%",
            }}
          >
            <GlitchText
              text={title}
              frame={frame}
              baseColor={accentColor}
              fontFamily={spaceGrotesk}
              fontSize={100}
              fontWeight={800}
            />
            <div style={{ marginTop: 20 }}>
              <GlitchText
                text={subtitle}
                frame={frame}
                baseColor="#A0A0AB"
                fontFamily={robotoMono}
                fontSize={36}
                fontWeight={400}
              />
            </div>
          </div>

          {/* Floating Cards Section */}
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              gap: 40,
              width: "80%",
              transformStyle: "preserve-3d",
            }}
          >
            {errorCodes.map((code, index) => {
              const cardDelay = 15 + index * 10;
              const appear = spring({
                fps,
                frame: frame - cardDelay,
                config: { damping: 12, stiffness: 90 },
              });

              const floatY = Math.sin((frame + index * 40) / 20) * 15;
              const cardScale = interpolate(appear, [0, 1], [0.8, 1]);
              const cardOpacity = interpolate(appear, [0, 1], [0, 1]);
              const cardZ = interpolate(appear, [0, 1], [-300, 0]);

              const glitchSeed = random(`card-glitch-${index}-${Math.floor(frame / 4)}`);
              const isGlitching = glitchSeed > 0.9;
              const glitchX = isGlitching ? random(`gx-${frame}`) * 20 - 10 : 0;
              const borderColor = isGlitching ? accentColor : "rgba(255, 255, 255, 0.1)";

              return (
                <div
                  key={index}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "space-between",
                    padding: "40px 50px",
                    background: "rgba(20, 20, 22, 0.7)",
                    border: `2px solid ${borderColor}`,
                    borderRadius: 24,
                    opacity: cardOpacity,
                    transform: `translate3d(${glitchX}px, ${floatY}px, ${cardZ}px) scale(${cardScale})`,
                    boxShadow: isGlitching
                      ? `0 0 40px ${accentColor}80`
                      : "0 20px 40px rgba(0,0,0,0.5)",
                    transition: "none",
                  }}
                >
                  <div style={{ display: "flex", alignItems: "center", gap: 30 }}>
                    <BrokenImageIcon
                      color={isGlitching ? accentColor : "#FFFFFF"}
                      size={64}
                      isGlitch={isGlitching}
                    />
                    <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                      <GlitchText
                        text={`> ${code}`}
                        frame={frame}
                        baseColor="#FFFFFF"
                        fontFamily={robotoMono}
                        fontSize={32}
                        fontWeight={600}
                      />
                      <GlitchText
                        text="Estado: Archivo Dañado"
                        frame={frame}
                        baseColor={accentColor}
                        fontFamily={robotoMono}
                        fontSize={24}
                        fontWeight={400}
                      />
                    </div>
                  </div>
                  <div
                    style={{
                      fontFamily: robotoMono,
                      fontSize: 32,
                      color: isGlitching ? "#FFFFFF" : "#555555",
                      fontWeight: 700,
                    }}
                  >
                    FAIL
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default ImageFormatError;